CREATE OR REPLACE FUNCTION public.filtered_reporting_quotes(filters jsonb DEFAULT '{}'::jsonb)
 RETURNS SETOF quotes LANGUAGE sql STABLE SET search_path TO 'public'
AS $function$ SELECT q.* FROM public.quotes q WHERE public.is_operator(auth.uid()) AND (coalesce(filters->>'status','all')='all' OR q.status::text=filters->>'status') AND (coalesce(filters->>'priority','all')='all' OR q.priority::text=filters->>'priority') AND (coalesce(filters->>'insurance','all')='all' OR (filters->>'insurance'='sgi_any' AND q.insurance_method LIKE 'sgi%') OR q.insurance_method=filters->>'insurance') AND (coalesce(filters->>'service','all')='all' OR q.requested_service=filters->>'service') AND (coalesce(filters->>'conversion','all')='all' OR q.conversion_status=filters->>'conversion') AND (coalesce(filters->>'search','')='' OR strpos(lower(concat_ws(' ',q.public_reference,q.customer_name,q.customer_phone,q.customer_email,q.vehicle_make,q.vehicle_model)),lower(filters->>'search'))>0) AND (coalesce(jsonb_array_length(filters->'months'),0)=0 OR to_char(q.created_at AT TIME ZONE 'America/Regina','YYYY-MM') IN (SELECT jsonb_array_elements_text(filters->'months'))) AND (nullif(filters->>'startDate','') IS NULL OR q.created_at>= (nullif(filters->>'startDate','')::date::timestamp AT TIME ZONE 'America/Regina')) AND (nullif(filters->>'endDate','') IS NULL OR q.created_at< ((nullif(filters->>'endDate','')::date+1)::timestamp AT TIME ZONE 'America/Regina')) AND (coalesce(jsonb_array_length(filters->'regions'),0)=0 OR public.phone_region_code(q.customer_phone) IN (SELECT jsonb_array_elements_text(filters->'regions'))); $function$;